### Describe the bug

An HMR update stamps every importer above a self-accepting module with the new `lastHMRTimestamp`, even though the update stops at that module and the browser keeps the importers' existing instances. From then on, any newly served import of one of those importers carries `?t=<new>`. To the browser that is a new URL, so the first lazy import after the update loads and evaluates the importer again, beside the instance the page already runs. Its module state is duplicated: singletons, registries, context objects and side effects run twice.

Graph:

```
main.js -> P.js -> Bd.js (import.meta.hot.accept()) -> L.js
Q.js -> P.js      (Q.js is imported lazily by main.js)
```

Editing `L.js` updates `Bd.js`, which accepts itself, so the page is correct after the update and `P.js` is not re-run. Then `import("./Q.js")` is served with `import "/P.js?t=<new>"`, and `P.js` evaluates a second time.

The stamp comes from `EnvironmentModuleGraph.invalidateModule`. It walks `mod.importers` and stops only at an importer that accepts `mod` as a dependency (`importer.acceptedHmrDeps.has(mod)`). A module that accepts itself does not stop the walk, so with `isHmr = true` every importer above it gets `lastHMRTimestamp = timestamp`. Import analysis then injects `t=${mod.lastHMRTimestamp}` into every later import of those modules.

The importers above the boundary do need their transform invalidated (their served code embeds the boundary's URL). They do not need a new HMR timestamp, because the browser did not replace them. Stamping only the modules up to and including the accepting boundary would keep their URLs stable.

### Reproduction

`package.json`:

```json
{"name":"repro","private":true,"type":"module","dependencies":{"playwright-core":"1.56.1","vite":"8.3.5"}}
```

`repro.mjs` (writes the app into `./app`, runs a real dev server, drives headless Chrome; "control" skips the edit):

```js
// node repro.mjs   (needs Google Chrome installed; set CHROME_PATH to use another Chromium binary)
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { createServer as createNetServer } from "node:net";
import { join } from "node:path";
import { chromium } from "playwright-core";
import { createServer, version } from "vite";

const root = join(import.meta.dirname, "app");

const files = {
  "index.html": `<!doctype html>\n<html><head><link rel="icon" href="data:,"></head><body><script type="module" src="/main.js"></script></body></html>\n`,
  "main.js": `import "./P.js";\nwindow.loadLazy = () => import("./Q.js");\nwindow.appReady = true;\n`,
  "P.js": `import { b } from "./Bd.js";\nglobalThis.pEvaluations = (globalThis.pEvaluations ?? 0) + 1;\nconsole.log("P evaluated #" + globalThis.pEvaluations + " as " + new URL(import.meta.url).pathname + new URL(import.meta.url).search);\nexport const p = "P:" + b;\n`,
  "Bd.js": `import { l } from "./L.js";\nexport const b = "Bd:" + l;\nif (import.meta.hot) import.meta.hot.accept();\n`,
  "L.js": `export const l = "L1";\n`,
  "Q.js": `import { p } from "./P.js";\nexport const q = p;\n`,
};

const freePort = () =>
  new Promise((resolve) => {
    const s = createNetServer().listen(0, "127.0.0.1", () => {
      const { port } = s.address();
      s.close(() => resolve(port));
    });
  });

async function scenario(name, browser) {
  rmSync(root, { force: true, recursive: true });
  mkdirSync(root, { recursive: true });
  for (const [file, body] of Object.entries(files)) writeFileSync(join(root, file), body);

  const port = await freePort();
  const server = await createServer({ configFile: false, logLevel: "silent", root, server: { host: "127.0.0.1", port, strictPort: true } });
  await server.listen();
  const origin = `http://127.0.0.1:${port}`;

  const page = await browser.newPage();
  const logs = [];
  page.on("console", (m) => logs.push(m.text()));
  await page.goto(`${origin}/`);
  await page.waitForFunction(() => window.appReady === true);
  await new Promise((r) => setTimeout(r, 300)); // let the watcher finish its initial scan

  if (name === "edit") {
    const hotUpdated = page.waitForEvent("console", { predicate: (m) => m.text().includes("hot updated"), timeout: 10_000 });
    writeFileSync(join(root, "L.js"), `export const l = "L2";\n`);
    await hotUpdated;
  }

  const qServed = await fetch(`${origin}/Q.js`).then((r) => r.text());
  await page.evaluate(() => window.loadLazy());
  const pEvaluations = await page.evaluate(() => globalThis.pEvaluations);
  const pUrlsLoaded = await page.evaluate(() =>
    performance
      .getEntriesByType("resource")
      .map((e) => new URL(e.name))
      .filter((u) => u.pathname === "/P.js")
      .map((u) => u.pathname + u.search),
  );

  console.log(`\n== ${name} ==`);
  console.log(`Q.js as served imports P as: ${qServed.match(/from\s+"([^"]*P\.js[^"]*)"/)?.[1]}`);
  console.log(`P.js URLs the page fetched: ${JSON.stringify(pUrlsLoaded)}`);
  console.log(`browser console:\n  ${logs.join("\n  ")}`);
  console.log(`P evaluations: ${pEvaluations} (expected 1)`);

  await page.close();
  await server.close();
}

console.log(`vite ${version}, node ${process.version}`);
const browser = await chromium.launch(process.env.CHROME_PATH ? { executablePath: process.env.CHROME_PATH } : { channel: "chrome" });
try {
  await scenario("control", browser);
  await scenario("edit", browser);
} finally {
  await browser.close();
  rmSync(root, { force: true, recursive: true });
}
```

### Steps to reproduce

```sh
npm install
node repro.mjs
```

```
vite 8.3.5, node v24.22.1

== control ==
Q.js as served imports P as: /P.js
P.js URLs the page fetched: ["/P.js"]
browser console:
  [vite] connecting...
  P evaluated #1 as /P.js
  [vite] connected.
P evaluations: 1 (expected 1)

== edit ==
Q.js as served imports P as: /P.js?t=1793301508245
P.js URLs the page fetched: ["/P.js","/P.js?t=1793301508245"]
browser console:
  [vite] connecting...
  P evaluated #1 as /P.js
  [vite] connected.
  [vite] hot updated: /Bd.js
  P evaluated #2 as /P.js?t=1793301508245
P evaluations: 2 (expected 1)
```

Expected: `P.js` evaluates once in both scenarios, and `Q.js` imports it as `/P.js`, the URL the page already holds.

