### Describe the bug

When a plugin calls `environment.reloadModule(mod)` while an earlier transform of that module is still running, the HMR fetch that follows is served the earlier transform's code, and that stale result is stored as the module's `transformResult`. Every later request gets the stale code until something invalidates the module again.

A file save is not affected, because `onFileChange` invalidates the module through `moduleGraph.invalidateModule(mod)`, which sets `lastInvalidationTimestamp`. `reloadModule()` only reaches `updateModules`, which calls `invalidateModule(mod, seen, timestamp, true)`. With `isHmr = true`, that sets `lastHMRTimestamp` and leaves `lastInvalidationTimestamp` alone.

Both race guards in `transformRequest.ts` compare against `lastInvalidationTimestamp`:

1. `transformRequest` reuses a pending request when `pending.timestamp > module.lastInvalidationTimestamp`, so the `?t=` fetch for the new update joins the in-flight transform of the old state.
2. `loadAndTransform` stores the result when `timestamp > mod.lastInvalidationTimestamp`, so the old result is cached as current.

Neither guard sees an invalidation that came through `reloadModule()`. Plugins that serve modules built from in-memory state (virtual modules, generated route manifests) use `reloadModule()` for exactly this case, and their transforms are often the slow ones.

Calling `environment.moduleGraph.invalidateModule(mod)` before `reloadModule(mod)` makes the repro below pass (0 stale runs of 20, from 20 of 20), so `reloadModule` doing that invalidation itself, as `onFileChange` does, looks like the fix.

### Reproduction

`package.json`:

```json
{"name":"repro","private":true,"type":"module","dependencies":{"vite":"8.3.5"}}
```

`repro.mjs` (a plugin serves `virtual:state` from in-memory state and calls `reloadModule()` when the state changes; the script acts as the HMR client):

```js
// node repro.mjs     (env: DELAY_MS=150 GAP_MS=50 RUNS=20 VERBOSE=1)
import { createServer as createNetServer } from "node:net";
import { setTimeout as sleep } from "node:timers/promises";
import { createServer, version } from "vite";

const DELAY_MS = Number(process.env.DELAY_MS ?? 150);
const GAP_MS = Number(process.env.GAP_MS ?? 50);
const RUNS = Number(process.env.RUNS ?? 20);
const VERBOSE = process.env.VERBOSE === "1";
const tagOf = (code) => code.match(/version = "(v\d)"/)?.[1] ?? "?";

const freePort = () =>
  new Promise((resolve) => {
    const s = createNetServer().listen(0, "127.0.0.1", () => {
      const { port } = s.address();
      s.close(() => resolve(port));
    });
  });

function statePlugin() {
  const state = { version: "v0" };
  return {
    name: "state-module",
    resolveId: (id) => (id === "/@state" || id === "virtual:state" ? "\0virtual:state" : undefined),
    load(id) {
      if (id === "\0virtual:state") return `export const version = "${state.version}";\nif (import.meta.hot) import.meta.hot.accept();\n`;
    },
    async transform(_code, id) {
      if (id === "\0virtual:state") await sleep(DELAY_MS); // any slow transform
    },
    async setVersion(server, next) {
      state.version = next;
      const env = server.environments.client;
      const mod = env.moduleGraph.getModuleById("\0virtual:state");
      if (mod) await env.reloadModule(mod);
    },
  };
}

async function run(index) {
  const plugin = statePlugin();
  const port = await freePort();
  const server = await createServer({
    appType: "custom",
    configFile: false,
    logLevel: "silent",
    plugins: [plugin],
    root: import.meta.dirname,
    server: { host: "127.0.0.1", port, strictPort: true, watch: null },
  });
  await server.listen();
  const origin = `http://127.0.0.1:${port}`;
  const t0 = performance.now();
  const log = (msg) => VERBOSE && console.log(`  [run ${index}] +${(performance.now() - t0).toFixed(0)}ms ${msg}`);

  await fetch(`${origin}/@id/__x00__virtual:state`).then((r) => r.text()); // first load: enters the graph as self-accepting

  const hmrFetches = [];
  const ws = new WebSocket(`ws://127.0.0.1:${port}/?token=${server.config.webSocketToken}`, "vite-hmr");
  await new Promise((resolve, reject) => {
    ws.addEventListener("open", resolve, { once: true });
    ws.addEventListener("error", reject, { once: true });
  });
  ws.addEventListener("message", (event) => {
    const payload = JSON.parse(event.data);
    if (payload.type !== "update") return;
    for (const update of payload.updates) {
      // Same wrapping as the client's wrapIdIfNeeded for ids that are not paths.
      const path = update.acceptedPath[0] === "/" ? update.acceptedPath : `/@id/${update.acceptedPath.replace("\0", "__x00__")}`;
      log(`update received, fetching ${path}?t=${update.timestamp}`);
      hmrFetches.push(fetch(`${origin}${path}?t=${update.timestamp}`).then((r) => r.text()).then(tagOf));
    }
  });

  await plugin.setVersion(server, "v1");
  await sleep(GAP_MS);
  await plugin.setVersion(server, "v2");

  await sleep(DELAY_MS * 3 + 300);
  const served = await Promise.all(hmrFetches);
  const reload = tagOf(await fetch(`${origin}/@id/__x00__virtual:state`).then((r) => r.text()));
  ws.close();
  await server.close();
  return { hmrUpdates: served.length, lastHmrFetchServed: served.at(-1) ?? "none", reloadServed: reload };
}

console.log(`vite ${version}, node ${process.version}, DELAY_MS=${DELAY_MS} GAP_MS=${GAP_MS} RUNS=${RUNS}`);
let stale = 0;
for (let i = 1; i <= RUNS; i++) {
  const r = await run(i);
  if (r.reloadServed !== "v2") stale++;
  console.log(`run ${String(i).padStart(2)}: hmr updates=${r.hmrUpdates} last HMR fetch served=${r.lastHmrFetchServed} plain request afterwards served=${r.reloadServed}${r.reloadServed === "v2" ? "" : "  <-- STALE (state is v2)"}`);
}
console.log(`\nstale after settle: ${stale}/${RUNS} runs (expected 0: the state is v2)`);
```

### Steps to reproduce

```sh
npm install
RUNS=5 node repro.mjs
```

```
vite 8.3.5, node v24.22.1, DELAY_MS=150 GAP_MS=50 RUNS=5
run  1: hmr updates=2 last HMR fetch served=v1 plain request afterwards served=v1  <-- STALE (state is v2)
run  2: hmr updates=2 last HMR fetch served=v1 plain request afterwards served=v1  <-- STALE (state is v2)
run  3: hmr updates=2 last HMR fetch served=v1 plain request afterwards served=v1  <-- STALE (state is v2)
run  4: hmr updates=2 last HMR fetch served=v1 plain request afterwards served=v1  <-- STALE (state is v2)
run  5: hmr updates=2 last HMR fetch served=v1 plain request afterwards served=v1  <-- STALE (state is v2)

stale after settle: 5/5 runs (expected 0: the state is v2)
```

The window is the transform's duration. With `DELAY_MS=150`, every run is stale for `GAP_MS` from 5 to 140 and none is for `GAP_MS` 160 or more. Expected: once the state is `v2` and the server has settled, every request serves `v2`.

